function articleCommentsUrl(slug) {
  return `/api/articles/${encodeURIComponent(slug)}/comments`;
}

async function requestJson(url, failureMessage, options = {}) {
  const res = await fetch(url, options);

  if (!res.ok) {
    throw new Error(`${failureMessage}: ${res.status}`);
  }

  return res.json();
}

export async function getComments(slug, options = {}) {
  const data = await requestJson(
    articleCommentsUrl(slug),
    "Failed to load comments",
    options,
  );

  return data.comments;
}

import { useEffect, useState } from "react";
import { getComments } from "./api";

function createEmptyState() {
  return {
    comments: [],
    error: null,
  };
}

function createLoadedState(comments) {
  return {
    comments,
    error: null,
  };
}

function createErrorState(error) {
  return {
    comments: [],
    error: error.message,
  };
}

function isAbortError(error) {
  return error.name === "AbortError";
}

function useComments(slug) {
  const [state, setState] = useState(createEmptyState);

  useEffect(() => {
    const controller = new AbortController();

    setState(createEmptyState());

    getComments(slug, { signal: controller.signal })
      .then((comments) => {
        if (!controller.signal.aborted) {
          setState(createLoadedState(comments));
        }
      })
      .catch((err) => {
        if (!controller.signal.aborted && !isAbortError(err)) {
          setState(createErrorState(err));
        }
      });

    return () => {
      controller.abort();
    };
  }, [slug]);

  return state;
}

export default useComments;

